using System;using System.ComponentModel;using System.Drawing.Design;using System.Linq;using System.Windows.Forms;using System.Windows.Forms.Design;//https://stackoverflow.com/questions/32582504/propertygrid-expandable-collection// Dislpay collection length in propertyGrid fieldnamespace LessonEditor.components {    public partial class StringArrayEditor : UITypeEditor {        public StringArrayEditor() {        }        public override UITypeEditorEditStyle GetEditStyle(ITypeDescriptorContext context) {            return UITypeEditorEditStyle.Modal;        }        public override object EditValue(ITypeDescriptorContext context, IServiceProvider provider, object value) {            var editorService = provider.GetService(typeof(IWindowsFormsEditorService)) as IWindowsFormsEditorService;            if (editorService != null) {                // Read Arguments                string message = string.Empty, title = string.Empty;                //get attributes with your arguments. there should be one such attribute.                var propertyattributes = context.PropertyDescriptor.Attributes.OfType<Arguments>();                if (propertyattributes.Count() > 0) {                    var argumentsattribute = propertyattributes.First();                    message = argumentsattribute.Message;                    title = argumentsattribute.Title;                }                // Show custom Text Editor Form                var selectionControl = new StringArrayPropertyForm((string[])value, message, title);                editorService.ShowDialog(selectionControl);                //Console.WriteLine("StringArrayEditor > EditValue > DialogResult:{0} Value:{1}", selectionControl.DialogResult, selectionControl.Value.ListToString("\n\t"));                if (selectionControl.DialogResult == DialogResult.OK) value = selectionControl.Value;            }            return value ?? new string[] { };        }        /// <summary>        /// Customize message and title for StringArrayPropertyForm        /// [StringArrayEditor.Arguments("Na každém řádku je text odpovídající jednomu sektoru.", "Textový editor:")]        /// [editor(typeof(StringArrayEditor), typeof(uitypeeditor))]        /// public object foo { get; set; }        /// </summary>        internal class Arguments : Attribute {            public string Message { get; private set; }            public string Title { get; private set; }            public Arguments(string message, string title) {                Message = message;                Title = title;            }        }    }}